def get_icd10(code: str) -> Optional[ICD10Entry]:
    return ICD10_CM_DATABASE.get(code.upper().strip())

def search_icd10(query: str, limit: int = 25) -> List[ICD10Entry]:
    q = query.lower()
    results = []
    for entry in ICD10_CM_DATABASE.values():
        if q in entry.code.lower() or q in entry.description.lower():
            results.append(entry)
            if len(results) >= limit:
                break
    return results
